import os
import sys
import fire
from PyPDF2 import PdfReader

sys.path.insert(0, os.path.join(os.path.dirname(os.path.abspath(__file__)), ".."))
from _log import log_tool_call


def _read_file(pdf_file_path):
    reader = PdfReader(pdf_file_path)
    text = ""
    for page in reader.pages:
        text += page.extract_text()
    return text


@log_tool_call("pdf.read_file")
def main(pdf_file_path):
    if not os.path.exists(pdf_file_path):
        return f"OBSERVATION: The pdf file {pdf_file_path} does not exist. Failed to read the file."
    return "OBSERVATION: " + _read_file(pdf_file_path)


if __name__ == "__main__":
    fire.Fire(main)

import os
import sys
import fire
import pytesseract
from PIL import Image

sys.path.insert(0, os.path.join(os.path.dirname(os.path.abspath(__file__)), ".."))
from _log import log_tool_call


def _recognize_file(file_path):
    try:
        return pytesseract.image_to_string(Image.open(file_path))
    except Exception:
        return None


@log_tool_call("ocr.recognize_file")
def main(file_path):
    if not os.path.exists(file_path):
        return f"OBSERVATION: The file {file_path} does not exist. Failed to recognize text."
    text = _recognize_file(file_path)
    if text:
        return f"OBSERVATION: The text from {file_path} is:\n{text}"
    return f"OBSERVATION: Failed to recognize text from {file_path}"


if __name__ == "__main__":
    fire.Fire(main)

import os
import sys
import fire
import fitz

sys.path.insert(0, os.path.join(os.path.dirname(os.path.abspath(__file__)), ".."))
from _log import log_tool_call


def _convert_to_image(pdf_file_path, image_file_path):
    try:
        with fitz.open(pdf_file_path) as doc:
            page = doc.load_page(0)
            pix = page.get_pixmap()
            pix.save(image_file_path)
        return True
    except Exception:
        return False


@log_tool_call("pdf.convert_to_image")
def main(pdf_file_path, image_file_path):
    if not os.path.exists(pdf_file_path):
        return f"OBSERVATION: The file {pdf_file_path} does not exist. Failed to convert pdf to image."
    success = _convert_to_image(pdf_file_path, image_file_path)
    if success:
        return f"OBSERVATION: Successfully convert {pdf_file_path} to {image_file_path}"
    return f"OBSERVATION: Failed to convert {pdf_file_path} to {image_file_path}"


if __name__ == "__main__":
    fire.Fire(main)

import os
import sys
import fire
import subprocess

sys.path.insert(0, os.path.join(os.path.dirname(os.path.abspath(__file__)), ".."))
from _log import log_tool_call

TESTBED_DIR = os.environ.get("OFFICEBENCH_TESTBED", "/workspace/testbed")


@log_tool_call("shell.command")
def main(command):
    if isinstance(command, list):
        command = " ".join(command)
    try:
        result = subprocess.run(
            command, shell=True, capture_output=True, text=True, cwd=TESTBED_DIR
        )
        output = result.stdout + result.stderr
        return f"OBSERVATION: Successfully executed command: {command}. The output was [{output}]."
    except Exception as e:
        return f"OBSERVATION: Failed to execute command: {command}. Error: {e}"


if __name__ == "__main__":
    fire.Fire(main)

